import{_ as t,o as s,c as a,ah as r}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Emplois du temps","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/emplois-du-temps.md","filePath":"src/guide/admin/emplois-du-temps.md"}'),n={name:"guide/admin/emplois-du-temps.md"};function i(o,e,l,u,d,p){return s(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="emplois-du-temps" tabindex="-1">Emplois du temps <a class="header-anchor" href="#emplois-du-temps" aria-label="Permalink to &quot;Emplois du temps&quot;">​</a></h1><p>Cette page couvre la construction de l&#39;emploi du temps hebdomadaire d&#39;une classe. Elle suppose que la classe existe déjà et qu&#39;au moins un enseignant lui est affecté (voir <a href="/era-guide/guide/admin/personnel-utilisateurs.html">Personnel et comptes utilisateurs</a>) — sans affectation enseignant, vous ne pouvez ajouter aucun créneau.</p><h2 id="construire-l-emploi-du-temps-d-une-classe" tabindex="-1">Construire l&#39;emploi du temps d&#39;une classe <a class="header-anchor" href="#construire-l-emploi-du-temps-d-une-classe" aria-label="Permalink to &quot;Construire l&#39;emploi du temps d&#39;une classe&quot;">​</a></h2><p>Depuis <strong>Structure scolaire → Classes</strong>, cliquez sur <strong>Emploi du temps</strong> sur la ligne de la classe concernée.</p><p>Pour ajouter un créneau :</p><ol><li>Cliquez sur <strong>Ajouter un créneau</strong>.</li><li>Renseignez les champs ci-dessous.</li><li>Répétez pour chaque créneau de la semaine. Le bouton (icône corbeille) sur une ligne retire ce créneau du formulaire.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><table tabindex="0"><thead><tr><th>Champ</th><th>Détail</th></tr></thead><tbody><tr><td>Jour</td><td>lundi à dimanche</td></tr><tr><td>Heure de début</td><td>—</td></tr><tr><td>Heure de fin</td><td>—</td></tr><tr><td>Enseignant / matière</td><td>liste des affectations enseignant existantes pour cette classe ; une affectation sans matière (classe qualitative) s&#39;affiche comme « Généraliste »</td></tr></tbody></table><p>Si aucun enseignant n&#39;est encore affecté à la classe, un message vous en informe et le bouton <strong>Ajouter un créneau</strong> reste désactivé — allez d&#39;abord créer les affectations enseignants nécessaires.</p><h2 id="exporter-l-emploi-du-temps" tabindex="-1">Exporter l&#39;emploi du temps <a class="header-anchor" href="#exporter-l-emploi-du-temps" aria-label="Permalink to &quot;Exporter l&#39;emploi du temps&quot;">​</a></h2><p>Le bouton <strong>Exporter vers un calendrier</strong> (en haut de la page) télécharge l&#39;emploi du temps de la classe au format calendrier, importable dans une application d&#39;agenda.</p>',10)])])}const h=t(n,[["render",i]]);export{m as __pageData,h as default};
